/**
 * Custom hook for UserManagement logic
 */

import { useMemo, useState, useEffect, useCallback } from 'react';
import {
  useUsersList,
  useStudentsList,
  useLecturersList,
  useCreateUser,
  useUpdateUser,
  useDeleteUser,
} from '@/hooks/useUsers';
import type { CreateUserRequest, UpdateUserRequest, Mahasiswa, Dosen } from '@/types';
import type { UserWithDetails, UserFormData, UserStats } from '../types';
import { getSqlValue, initialFormData } from '../types';

interface UseUserManagementReturn {
  // Data
  users: UserWithDetails[];
  students: Mahasiswa[];
  lecturers: Dosen[];
  userStats: UserStats;
  totalUsers: number;
  
  // Loading states
  loading: boolean;
  loadError: Error | null;
  actionLoading: boolean;
  
  // Pagination
  currentPage: number;
  itemsPerPage: number;
  setCurrentPage: (page: number) => void;
  
  // Search and filter
  searchTerm: string;
  setSearchTerm: (term: string) => void;
  selectedRole: string;
  setSelectedRole: (role: string) => void;
  filteredUsers: UserWithDetails[];
  
  // Form state
  formData: UserFormData;
  setFormData: React.Dispatch<React.SetStateAction<UserFormData>>;
  formError: string | null;
  setFormError: (error: string | null) => void;
  
  // Modal state
  isAddModalOpen: boolean;
  setIsAddModalOpen: (open: boolean) => void;
  isEditModalOpen: boolean;
  setIsEditModalOpen: (open: boolean) => void;
  editingUser: UserWithDetails | null;
  setEditingUser: (user: UserWithDetails | null) => void;
  
  // Actions
  handleAddUser: (e: React.FormEvent) => Promise<void>;
  handleEditUser: (e: React.FormEvent) => Promise<void>;
  handleDeleteUser: (user: UserWithDetails) => Promise<void>;
  openAddModal: () => void;
  openEditModal: (user: UserWithDetails) => void;
  closeAddModal: () => void;
  closeEditModal: () => void;
  
  // Role management
  addRole: (role: string) => void;
  removeRole: (index: number) => void;
  updateRoleEntity: (index: number, entityType: string, entityId: string) => void;
}

export function useUserManagement(): UseUserManagementReturn {
  // Pagination state
  const [currentPage, setCurrentPage] = useState(1);
  const [totalUsers, setTotalUsers] = useState(0);
  const itemsPerPage = 50;

  // Search and filter state
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedRole, setSelectedRole] = useState<string>('all');

  // Modal state
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [editingUser, setEditingUser] = useState<UserWithDetails | null>(null);

  // Form state
  const [formData, setFormData] = useState<UserFormData>(initialFormData);
  const [formError, setFormError] = useState<string | null>(null);
  const [actionLoading, setActionLoading] = useState(false);

  // Local entity state
  const [students, setStudents] = useState<Mahasiswa[]>([]);
  const [lecturers, setLecturers] = useState<Dosen[]>([]);

  // Queries
  const { data: studentsData, isLoading: isStudentsLoading, error: studentsError } = useStudentsList();
  const { data: lecturersData, isLoading: isLecturersLoading, error: lecturersError } = useLecturersList();
  
  const usersParams = useMemo(
    () => ({
      q: searchTerm || undefined,
      limit: itemsPerPage,
      offset: (currentPage - 1) * itemsPerPage,
    }),
    [itemsPerPage, currentPage, searchTerm]
  );
  
  const usersQuery = useUsersList(usersParams, { enabled: true });

  // Mutations
  const createUserMutation = useCreateUser();
  const updateUserMutation = useUpdateUser();
  const deleteUserMutation = useDeleteUser();

  // Sync local state with query data
  useEffect(() => {
    if (studentsData) setStudents(studentsData);
  }, [studentsData]);

  useEffect(() => {
    if (lecturersData) setLecturers(lecturersData);
  }, [lecturersData]);

  useEffect(() => {
    if (usersQuery.data) {
      setTotalUsers(usersQuery.data.data.total);
    }
  }, [usersQuery.data]);

  // Reset page on search/filter change
  useEffect(() => {
    setCurrentPage(1);
  }, [searchTerm, selectedRole]);

  // Derived state
  const loading = usersQuery.isLoading || isStudentsLoading || isLecturersLoading;
  const loadError = usersQuery.error || studentsError || lecturersError;

  // Enrich users with entity info
  const users: UserWithDetails[] = useMemo(() => {
    const base = usersQuery.data?.data?.data ?? [];

    if (!Array.isArray(base)) {
      return [];
    }
    
    return base.map((user) => {
      const userRoles = user.roles || [];
      const studentRole = userRoles.find((r) => r.role === 'student');
      const lecturerRole = userRoles.find((r) => r.role === 'lecturer');
      const enriched: UserWithDetails = { ...user };
      
      if (studentRole?.entity_id && studentsData) {
        enriched.studentInfo = studentsData.find((s) => s.nim === studentRole.entity_id);
      }
      if (lecturerRole?.entity_id && lecturersData) {
        enriched.lecturerInfo = lecturersData.find((l) => l.id === lecturerRole.entity_id);
      }
      
      return enriched;
    });
  }, [usersQuery.data, studentsData, lecturersData]);

  // Filter users client-side (for role filter)
  const filteredUsers = useMemo(() => {
    return users.filter((user) => {
      const userRoles = user.roles?.map((r) => r.role) || [];
      return selectedRole === 'all' || userRoles.includes(selectedRole);
    });
  }, [users, selectedRole]);

  // Calculate stats
  const userStats: UserStats = useMemo(() => {
    const allRoles = users.flatMap((u) => u.roles?.map((r) => r.role) || []);
    return {
      total: totalUsers,
      students: allRoles.filter((r) => r === 'student').length,
      lecturers: allRoles.filter((r) => r === 'lecturer').length,
      admins: allRoles.filter((r) => r === 'admin').length,
      staff: allRoles.filter((r) => r === 'staff').length,
    };
  }, [users, totalUsers]);

  // Modal handlers
  const openAddModal = useCallback(() => {
    setFormError(null);
    setFormData(initialFormData);
    setIsAddModalOpen(true);
  }, []);

  const closeAddModal = useCallback(() => {
    setIsAddModalOpen(false);
  }, []);

  const openEditModal = useCallback((user: UserWithDetails) => {
    setFormError(null);
    setEditingUser(user);
    setFormData({
      email: user.email,
      name: getSqlValue(user.name),
      password: '',
      roles: user.roles || [],
    });
    setIsEditModalOpen(true);
  }, []);

  const closeEditModal = useCallback(() => {
    setIsEditModalOpen(false);
    setEditingUser(null);
  }, []);

  // Form actions
  const handleAddUser = useCallback(async (e: React.FormEvent) => {
    e.preventDefault();
    setFormError(null);

    if (!formData.email.trim() || !formData.email.includes('@')) {
      setFormError('Email tidak valid');
      return;
    }

    if (!formData.password.trim()) {
      setFormError('Password wajib diisi jika tidak menggunakan Google OAuth');
      return;
    }

    setActionLoading(true);
    try {
      const payload: CreateUserRequest = {
        email: formData.email.trim(),
        name: formData.name.trim() || undefined,
        password: formData.password.trim() || undefined,
        auth_provider: 'local',
        roles: formData.roles,
      };

      await createUserMutation.mutateAsync(payload);
      setIsAddModalOpen(false);
    } catch (error: unknown) {
      const err = error as Error;
      setFormError(err.message || 'Gagal menambahkan pengguna');
    } finally {
      setActionLoading(false);
    }
  }, [formData, createUserMutation]);

  const handleEditUser = useCallback(async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingUser) return;

    setFormError(null);

    if (!formData.email.trim() || !formData.email.includes('@')) {
      setFormError('Email tidak valid');
      return;
    }

    setActionLoading(true);
    try {
      const payload: UpdateUserRequest = {
        email: formData.email.trim(),
        name: formData.name.trim() || undefined,
        roles: formData.roles,
      };

      if (formData.password.trim()) {
        payload.password = formData.password.trim();
      }

      await updateUserMutation.mutateAsync({ id: editingUser.id, data: payload });
      setIsEditModalOpen(false);
    } catch (error: unknown) {
      const err = error as Error;
      setFormError(err.message || 'Gagal mengupdate pengguna');
    } finally {
      setActionLoading(false);
    }
  }, [formData, editingUser, updateUserMutation]);

  const handleDeleteUser = useCallback(async (user: UserWithDetails) => {
    const userName = getSqlValue(user.name) || user.email;
    if (!confirm(`Apakah Anda yakin ingin menghapus pengguna "${userName}"?`)) {
      return;
    }

    try {
      await deleteUserMutation.mutateAsync({ id: user.id });
    } catch (error: unknown) {
      const err = error as Error;
      alert(`Gagal menghapus pengguna: ${err.message}`);
    }
  }, [deleteUserMutation]);

  // Role management
  const addRole = useCallback((role: string) => {
    if (formData.roles.some((r) => r.role === role)) {
      setFormError(`Role sudah ditambahkan`);
      return;
    }

    setFormData((prev) => ({
      ...prev,
      roles: [...prev.roles, { role }],
    }));
  }, [formData.roles]);

  const removeRole = useCallback((index: number) => {
    setFormData((prev) => ({
      ...prev,
      roles: prev.roles.filter((_, i) => i !== index),
    }));
  }, []);

  const updateRoleEntity = useCallback((index: number, entityType: string, entityId: string) => {
    setFormData((prev) => {
      const newRoles = [...prev.roles];
      if (entityId) {
        newRoles[index] = {
          ...newRoles[index],
          entity_type: entityType,
          entity_id: entityId,
        };
      } else {
        const { entity_type, entity_id, ...rest } = newRoles[index];
        void entity_type;
        void entity_id;
        newRoles[index] = rest;
      }
      return { ...prev, roles: newRoles };
    });
  }, []);

  return {
    // Data
    users,
    students,
    lecturers,
    userStats,
    totalUsers,
    
    // Loading states
    loading,
    loadError,
    actionLoading,
    
    // Pagination
    currentPage,
    itemsPerPage,
    setCurrentPage,
    
    // Search and filter
    searchTerm,
    setSearchTerm,
    selectedRole,
    setSelectedRole,
    filteredUsers,
    
    // Form state
    formData,
    setFormData,
    formError,
    setFormError,
    
    // Modal state
    isAddModalOpen,
    setIsAddModalOpen,
    isEditModalOpen,
    setIsEditModalOpen,
    editingUser,
    setEditingUser,
    
    // Actions
    handleAddUser,
    handleEditUser,
    handleDeleteUser,
    openAddModal,
    openEditModal,
    closeAddModal,
    closeEditModal,
    
    // Role management
    addRole,
    removeRole,
    updateRoleEntity,
  };
}

export default useUserManagement;
