/**
 * User Management Page
 * 
 * Refactored to use smaller components for better maintainability.
 * This is the main entry point that composes all sub-components.
 */

import React, { useState } from 'react';
import { Plus, Search, Filter } from 'lucide-react';
import { PageHeader } from '@/components/ui';
import { UserStatsCards } from './UserStatsCards';
import { UserTable } from './UserTable';
import { UserFormModal } from './UserFormModal';
import { UserAssignments } from './UserAssignments';
import { useUserManagement } from '../hooks/useUserManagement';
import { useAuth, useTranslation } from '@/contexts';
import type { UserWithDetails } from '../types';

const UserManagement: React.FC = () => {
  const { currentSemester } = useAuth();
  const { t } = useTranslation();
  const [assignmentsUser, setAssignmentsUser] = useState<UserWithDetails | null>(null);
  
  const {
    // Data
    students,
    lecturers,
    userStats,
    totalUsers,
    
    // Loading states
    loading,
    loadError,
    actionLoading,
    
    // Pagination
    currentPage,
    itemsPerPage,
    setCurrentPage,
    
    // Search and filter
    searchTerm,
    setSearchTerm,
    selectedRole,
    setSelectedRole,
    filteredUsers,
    
    // Form state
    formData,
    setFormData,
    formError,
    
    // Modal state
    isAddModalOpen,
    isEditModalOpen,
    
    // Actions
    handleAddUser,
    handleEditUser,
    handleDeleteUser,
    openAddModal,
    openEditModal,
    closeAddModal,
    closeEditModal,
    
    // Role management
    addRole,
    removeRole,
    updateRoleEntity,
  } = useUserManagement();

  // Handle form change
  const handleFormChange = (data: Partial<typeof formData>) => {
    setFormData((prev) => ({ ...prev, ...data }));
  };

  return (
    <div className="p-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between mb-6">
        <PageHeader
          title={t('adminUsers.title')}
          subtitle={t('adminUsers.subtitle')}
        />
        <div className="flex gap-2 mt-4 sm:mt-0">
          <button
            onClick={openAddModal}
            className="inline-flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
          >
            <Plus className="w-4 h-4" />
            {t('adminUsers.addUser')}
          </button>
        </div>
      </div>

      {/* Error Display */}
      {loadError && (
        <div className="mb-6 p-4 bg-red-50 border border-red-200 rounded-lg text-red-600">
          {t('adminUsers.loadError')}: {loadError.message}
        </div>
      )}

      {/* Statistics */}
      <UserStatsCards stats={userStats} />

      {/* Search and Filter */}
      <div className="flex flex-col sm:flex-row gap-4 mb-6">
        {/* Search */}
        <div className="flex-1 relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
          <input
            type="text"
            placeholder="Cari berdasarkan nama atau email..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
          />
        </div>

        {/* Role Filter */}
        <div className="relative">
          <Filter className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
          <select
            value={selectedRole}
            onChange={(e) => setSelectedRole(e.target.value)}
            className="pl-10 pr-8 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 appearance-none bg-white"
          >
            <option value="all">Semua Role</option>
            <option value="admin">Admin</option>
            <option value="lecturer">Dosen</option>
            <option value="student">Mahasiswa</option>
            <option value="staff">Staff</option>
            <option value="alumni">Alumni</option>
            <option value="student_applicant">Pendaftar</option>
          </select>
        </div>
      </div>

      {/* User Table */}
      <UserTable
        users={filteredUsers}
        loading={loading}
        currentPage={currentPage}
        totalUsers={selectedRole === 'all' ? totalUsers : filteredUsers.length}
        itemsPerPage={itemsPerPage}
        onManageAssignments={setAssignmentsUser}
        onPageChange={setCurrentPage}
        onEditUser={openEditModal}
        onDeleteUser={handleDeleteUser}
      />

      {/* Add User Modal */}
      <UserFormModal
        isOpen={isAddModalOpen}
        isEdit={false}
        formData={formData}
        formError={formError}
        actionLoading={actionLoading}
        students={students}
        lecturers={lecturers}
        onClose={closeAddModal}
        onSubmit={handleAddUser}
        onFormChange={handleFormChange}
        onAddRole={addRole}
        onRemoveRole={removeRole}
        onUpdateRoleEntity={updateRoleEntity}
      />

      {/* Edit User Modal */}
      <UserFormModal
        isOpen={isEditModalOpen}
        isEdit={true}
        formData={formData}
        formError={formError}
        actionLoading={actionLoading}
        students={students}
        lecturers={lecturers}
        onClose={closeEditModal}
        onSubmit={handleEditUser}
        onFormChange={handleFormChange}
        onAddRole={addRole}
        onRemoveRole={removeRole}
        onUpdateRoleEntity={updateRoleEntity}
      />

      {/* User Assignments Modal */}
      <UserAssignments
        user={assignmentsUser!}
        isOpen={!!assignmentsUser}
        onClose={() => setAssignmentsUser(null)}
        currentSemester={currentSemester}
      />
    </div>
  );
};

export default UserManagement;
