import React from 'react';
import { Edit, Trash2, Mail, Phone, ChevronLeft, ChevronRight, BookOpen } from 'lucide-react';
import type { UserWithDetails } from '../types';
import { getRoleColor, getRoleLabel, getSqlValue } from '../types';

interface UserTableProps {
  users: UserWithDetails[];
  loading: boolean;
  currentPage: number;
  totalUsers: number;
  itemsPerPage: number;
  onPageChange: (page: number) => void;
  onEditUser: (user: UserWithDetails) => void;
  onDeleteUser: (user: UserWithDetails) => void;
  onManageAssignments: (user: UserWithDetails) => void;
}

export const UserTable: React.FC<UserTableProps> = ({
  users,
  loading,
  currentPage,
  totalUsers,
  itemsPerPage,
  onPageChange,
  onEditUser,
  onDeleteUser,
  onManageAssignments,
}) => {
  const totalPages = Math.ceil(totalUsers / itemsPerPage);

  return (
    <div className="bg-white rounded-lg border border-gray-200">
      {/* Table */}
      <div className="overflow-x-auto">
        <table className="w-full">
          <thead className="bg-gray-50 border-b border-gray-200">
            <tr>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                Pengguna
              </th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                Role
              </th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                Entitas
              </th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                Kontak
              </th>
              <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">
                Aksi
              </th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-200">
            {loading ? (
              <tr>
                <td colSpan={5} className="px-6 py-12 text-center">
                  <div className="flex items-center justify-center">
                    <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
                    <span className="ml-2 text-gray-500">Memuat data...</span>
                  </div>
                </td>
              </tr>
            ) : users.length === 0 ? (
              <tr>
                <td colSpan={5} className="px-6 py-12 text-center text-gray-500">
                  Tidak ada pengguna ditemukan
                </td>
              </tr>
            ) : (
              users.map((user) => (
                <UserTableRow
                  key={user.id}
                  user={user}
                  onEdit={onEditUser}
                  onDelete={onDeleteUser}
                  onManageAssignments={onManageAssignments}
                />
              ))
            )}
          </tbody>
        </table>
      </div>

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="px-6 py-4 border-t border-gray-200 flex items-center justify-between">
          <div className="text-sm text-gray-500">
            Menampilkan {(currentPage - 1) * itemsPerPage + 1} -{' '}
            {Math.min(currentPage * itemsPerPage, totalUsers)} dari {totalUsers} pengguna
          </div>
          <div className="flex items-center gap-2">
            <button
              onClick={() => onPageChange(currentPage - 1)}
              disabled={currentPage === 1}
              className="p-2 rounded-lg border border-gray-300 hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              <ChevronLeft className="w-4 h-4" />
            </button>
            <span className="text-sm text-gray-700">
              Halaman {currentPage} dari {totalPages}
            </span>
            <button
              onClick={() => onPageChange(currentPage + 1)}
              disabled={currentPage === totalPages}
              className="p-2 rounded-lg border border-gray-300 hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              <ChevronRight className="w-4 h-4" />
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

/**
 * Individual user row component
 */
interface UserTableRowProps {
  user: UserWithDetails;
  onEdit: (user: UserWithDetails) => void;
  onDelete: (user: UserWithDetails) => void;
  onManageAssignments: (user: UserWithDetails) => void;
}

const UserTableRow: React.FC<UserTableRowProps> = ({ user, onEdit, onDelete, onManageAssignments }) => {
  const userName = getSqlValue(user.name) || user.email.split('@')[0];
  const roles = user.roles || [];

  // Get contact info from entity
  const getContactInfo = () => {
    if (user.studentInfo) {
      return {
        email: getSqlValue(user.studentInfo.email),
        phone: getSqlValue(user.studentInfo.no_hp),
      };
    }
    if (user.lecturerInfo) {
      return {
        email: getSqlValue(user.lecturerInfo.email),
        phone: getSqlValue(user.lecturerInfo.no_hp),
      };
    }
    return { email: user.email, phone: '' };
  };

  const contact = getContactInfo();

  // Get entity info
  const getEntityInfo = () => {
    const entities: string[] = [];
    
    if (user.studentInfo) {
      entities.push(`NIM: ${user.studentInfo.nim}`);
    }
    if (user.lecturerInfo) {
      entities.push(`NIDN: ${getSqlValue(user.lecturerInfo.nuptk) || user.lecturerInfo.id}`);
    }
    
    return entities;
  };

  const entityInfo = getEntityInfo();

  return (
    <tr className="hover:bg-gray-50">
      <td className="px-6 py-4">
        <div className="flex items-center">
          <div className="h-10 w-10 flex-shrink-0">
            <div className="h-10 w-10 rounded-full bg-blue-100 flex items-center justify-center">
              <span className="text-blue-600 font-medium text-sm">
                {userName.charAt(0).toUpperCase()}
              </span>
            </div>
          </div>
          <div className="ml-4">
            <div className="text-sm font-medium text-gray-900">{userName}</div>
            <div className="text-sm text-gray-500">{user.email}</div>
          </div>
        </div>
      </td>
      <td className="px-6 py-4">
        <div className="flex flex-wrap gap-1">
          {roles.map((roleObj, idx) => (
            <span
              key={idx}
              className={`inline-flex items-center px-2 py-0.5 rounded text-xs font-medium ${getRoleColor(roleObj.role)}`}
            >
              {getRoleLabel(roleObj.role)}
            </span>
          ))}
          {roles.length === 0 && (
            <span className="text-gray-400 text-sm">-</span>
          )}
        </div>
      </td>
      <td className="px-6 py-4">
        <div className="text-sm text-gray-900">
          {entityInfo.length > 0 ? (
            entityInfo.map((info, idx) => (
              <div key={idx}>{info}</div>
            ))
          ) : (
            <span className="text-gray-400">-</span>
          )}
        </div>
      </td>
      <td className="px-6 py-4">
        <div className="text-sm text-gray-500 space-y-1">
          {contact.email && (
            <div className="flex items-center gap-1">
              <Mail className="w-3 h-3" />
              <span className="truncate max-w-[150px]">{contact.email}</span>
            </div>
          )}
          {contact.phone && (
            <div className="flex items-center gap-1">
              <Phone className="w-3 h-3" />
              {contact.phone}
            </div>
          )}
        </div>
      </td>
      <td className="px-6 py-4 text-right">
        <div className="flex items-center justify-end gap-2">
          {(user.roles?.some((r) => r.role === 'student' || r.role === 'lecturer')) && (
            <button
              onClick={() => onManageAssignments(user)}
              className="p-2 text-gray-400 hover:text-green-600 hover:bg-green-50 rounded-lg transition-colors"
              title="Manage Assignments"
            >
              <BookOpen className="w-4 h-4" />
            </button>
          )}
          <button
            onClick={() => onEdit(user)}
            className="p-2 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
            title="Edit"
          >
            <Edit className="w-4 h-4" />
          </button>
          <button
            onClick={() => onDelete(user)}
            className="p-2 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors"
            title="Hapus"
          >
            <Trash2 className="w-4 h-4" />
          </button>
        </div>
      </td>
    </tr>
  );
};

export default UserTable;
