/**
 * User Attendance Component (Admin View)
 * Displays a student's attendance record similar to the student's attendance page
 */

import React, { useMemo } from 'react';
import { useQuery } from '@tanstack/react-query';
import { CheckCircle, XCircle, Clock, AlertCircle, ClockAlert, Minus, Loader2 } from 'lucide-react';
import { apiService } from '@/services';
import type { AttendanceRecord, StudentClass, MeetingSchedule } from '@/types';
import { extractString, extractDate } from '@/utils';
import type { SqlNullString } from '@/types';

interface CourseAttendanceData {
  course: StudentClass;
  meetings: Array<{
    id: number;
    topik?: string;
    tgl_pertemuan: string;
    pertemuan_ke: number;
    attendance?: AttendanceRecord;
  }>;
  stats: {
    totalMeetings: number;
    attended: number;
    excused: number;
    sick: number;
    late: number;
    substitute: number;
    absent: number;
    attendancePercentage: number;
  };
}

interface UserAttendanceProps {
  studentId: string;
  semester: string;
}

export const UserAttendance: React.FC<UserAttendanceProps> = ({ studentId, semester }) => {
  // Fetch student classes
  const { data: studentClasses = [], isLoading: loadingClasses } = useQuery({
    queryKey: ['admin-student-classes', studentId, semester],
    queryFn: async () => {
      return await apiService.getStudentClasses(studentId, { semester });
    },
    enabled: !!studentId && !!semester,
  });

  // Fetch all meetings for student's classes
  const classIds = useMemo(() => studentClasses.map((c: StudentClass) => c.kelas_id).filter((id): id is number => id !== undefined), [studentClasses]);

  const meetingsQueries = useQuery({
    queryKey: ['admin-student-meetings', classIds],
    queryFn: async () => {
      if (classIds.length === 0) return {};

      const result: Record<number, MeetingSchedule[]> = {};

      await Promise.all(
        classIds.map(async (classId: number) => {
          try {
            const meetings = await apiService.getMeetingsByClass(classId);
            result[classId] = meetings;
          } catch (error) {
            result[classId] = [];
          }
        })
      );

      return result;
    },
    enabled: classIds.length > 0,
  });

  // Fetch attendances for all meetings
  const meetingIds = useMemo(() => {
    if (!meetingsQueries.data) return [];
    return Object.values(meetingsQueries.data).flat().map(m => m.id);
  }, [meetingsQueries.data]);

  const attendancesQuery = useQuery({
    queryKey: ['admin-student-attendances', studentId, meetingIds],
    queryFn: async () => {
      if (meetingIds.length === 0) return {};

      const result: Record<number, AttendanceRecord> = {};

      await Promise.all(
        meetingIds.map(async (meetingId) => {
          try {
            const attendances = await apiService.getMeetingAttendances(meetingId);
            const studentAttendance = attendances.find(a => a.nim === studentId);
            if (studentAttendance) {
              result[meetingId] = studentAttendance;
            }
          } catch (error) {
            // silently ignore
          }
        })
      );

      return result;
    },
    enabled: meetingIds.length > 0,
  });

  // Process data into course attendance groups with stats
  const courseAttendanceData = useMemo(() => {
    if (!meetingsQueries.data || !studentClasses.length) return [];

    return studentClasses
      .map((course: StudentClass) => {
        const meetings = (course.kelas_id !== undefined ? meetingsQueries.data?.[course.kelas_id] || [] : []).sort((a: MeetingSchedule, b: MeetingSchedule) => (a.pertemuan_ke || 0) - (b.pertemuan_ke || 0));

        const courseData: CourseAttendanceData = {
          course,
          meetings: meetings.map((m: MeetingSchedule) => ({
            id: m.id,
            topik: extractString(m.topik as string | SqlNullString),
            tgl_pertemuan: typeof m.tgl_pertemuan === 'string' ? m.tgl_pertemuan : m.tgl_pertemuan?.Time || '',
            pertemuan_ke: m.pertemuan_ke,
            attendance: attendancesQuery.data?.[m.id],
          })),
          stats: {
            totalMeetings: meetings.length,
            attended: 0,
            excused: 0,
            sick: 0,
            late: 0,
            substitute: 0,
            absent: 0,
            attendancePercentage: 0,
          },
        };

        // Calculate stats
        meetings.forEach((m: MeetingSchedule) => {
          const attendance = attendancesQuery.data?.[m.id];
          if (attendance) {
            const status = extractString(attendance.status_kehadiran as string | SqlNullString)?.toLowerCase();
            switch (status) {
              case 'hadir':
              case 'present':
                courseData.stats.attended++;
                break;
              case 'izin':
              case 'excused':
                courseData.stats.excused++;
                break;
              case 'sakit':
              case 'sick':
                courseData.stats.sick++;
                break;
              case 'terlambat':
              case 'late':
                courseData.stats.late++;
                break;
              case 'pengganti':
              case 'substitute':
                courseData.stats.substitute++;
                break;
              case 'alpa':
              case 'alfa':
              case 'absent':
                courseData.stats.absent++;
                break;
            }
          }
        });

        if (courseData.stats.totalMeetings > 0) {
          const presentMeetings = courseData.stats.attended + courseData.stats.late + courseData.stats.substitute;
          courseData.stats.attendancePercentage = Math.round((presentMeetings / courseData.stats.totalMeetings) * 100);
        }

        return courseData;
      })
      .sort((a: CourseAttendanceData, b: CourseAttendanceData) => extractString(a.course.kode_mk || '').localeCompare(extractString(b.course.kode_mk || '')));
  }, [studentClasses, meetingsQueries.data, attendancesQuery.data, studentId]);

  const isLoading = loadingClasses || meetingsQueries.isLoading || attendancesQuery.isLoading;

  const getStatusIcon = (status: string) => {
    switch (status?.toLowerCase()) {
      case 'hadir':
      case 'present':
        return <CheckCircle className="h-4 w-4 text-green-600" />;
      case 'izin':
      case 'excused':
        return <Clock className="h-4 w-4 text-blue-600" />;
      case 'sakit':
      case 'sick':
        return <AlertCircle className="h-4 w-4 text-yellow-600" />;
      case 'terlambat':
      case 'late':
        return <ClockAlert className="h-4 w-4 text-orange-600" />;
      case 'pengganti':
      case 'substitute':
        return <CheckCircle className="h-4 w-4 text-purple-600" />;
      case 'alpa':
      case 'alfa':
      case 'absent':
        return <XCircle className="h-4 w-4 text-red-600" />;
      default:
        return <Minus className="h-4 w-4 text-gray-300" />;
    }
  };

  const getAttendanceColorForPercentage = (percentage: number): string => {
    if (percentage >= 80) return 'text-green-600';
    if (percentage >= 70) return 'text-yellow-600';
    return 'text-red-600';
  };

  if (isLoading) {
    return (
      <div className="flex justify-center items-center py-8">
        <Loader2 className="h-6 w-6 animate-spin text-primary-600" />
        <span className="ml-2 text-gray-600">Loading attendance...</span>
      </div>
    );
  }

  if (courseAttendanceData.length === 0) {
    return (
      <div className="text-center py-8 text-gray-500">
        No attendance records found for this semester
      </div>
    );
  }

  return (
    <div className="space-y-3">
      {courseAttendanceData.map((courseData: CourseAttendanceData) => (
        <div key={courseData.course.kelas_id} className="bg-white border border-gray-200 rounded-lg overflow-hidden">
          {/* Course Info and Summary - Single Compact Row */}
          <div className="bg-gradient-to-r from-primary-50 to-secondary-50 px-3 py-2 border-b border-gray-200">
            <div className="flex justify-between items-center gap-3">
              <div className="flex-1 min-w-0">
                <h4 className="font-semibold text-sm text-gray-900 truncate">
                  {extractString(courseData.course.kode_mk || '')} - {extractString(courseData.course.nama_mk || '')}
                </h4>
                <p className="text-xs text-gray-600 truncate">
                  {extractString(courseData.course.nama_kelas || '')}
                </p>
              </div>
              
              {/* Compact Stats */}
              <div className="flex items-center gap-2 text-xs flex-shrink-0">
                <div className="text-center">
                  <div className={`font-bold text-base ${getAttendanceColorForPercentage(courseData.stats.attendancePercentage)}`}>
                    {courseData.stats.attendancePercentage}%
                  </div>
                </div>
                <div className="h-6 w-px bg-gray-300"></div>
                <div className="flex gap-1.5">
                  <span className="bg-green-100 text-green-700 px-1.5 py-0.5 rounded text-xs font-medium">{courseData.stats.attended}</span>
                  <span className="bg-orange-100 text-orange-700 px-1.5 py-0.5 rounded text-xs font-medium">{courseData.stats.late}</span>
                  <span className="bg-blue-100 text-blue-700 px-1.5 py-0.5 rounded text-xs font-medium">{courseData.stats.excused}</span>
                  <span className="bg-yellow-100 text-yellow-700 px-1.5 py-0.5 rounded text-xs font-medium">{courseData.stats.sick}</span>
                  <span className="bg-purple-100 text-purple-700 px-1.5 py-0.5 rounded text-xs font-medium">{courseData.stats.substitute}</span>
                  <span className="bg-red-100 text-red-700 px-1.5 py-0.5 rounded text-xs font-medium">{courseData.stats.absent}</span>
                </div>
              </div>
            </div>
          </div>

          {/* Attendance Grid - Weeks as Columns */}
          {courseData.meetings.length === 0 ? (
            <div className="p-3 text-center text-xs text-gray-500">
              No meetings recorded for this course.
            </div>
          ) : (
            <div className="p-3">
              <div className="flex gap-2 flex-wrap items-start">
                {/* Legend */}
                <div className="text-xs text-gray-600 mb-1 w-full">
                  <div className="flex gap-2 flex-wrap">
                    <div className="flex items-center gap-0.5">
                      <CheckCircle className="h-3 w-3 text-green-600" />
                      <span>Present</span>
                    </div>
                    <div className="flex items-center gap-0.5">
                      <ClockAlert className="h-3 w-3 text-orange-600" />
                      <span>Late</span>
                    </div>
                    <div className="flex items-center gap-0.5">
                      <Clock className="h-3 w-3 text-blue-600" />
                      <span>Excused</span>
                    </div>
                    <div className="flex items-center gap-0.5">
                      <AlertCircle className="h-3 w-3 text-yellow-600" />
                      <span>Sick</span>
                    </div>
                    <div className="flex items-center gap-0.5">
                      <CheckCircle className="h-3 w-3 text-purple-600" />
                      <span>Substitute</span>
                    </div>
                    <div className="flex items-center gap-0.5">
                      <XCircle className="h-3 w-3 text-red-600" />
                      <span>Absent</span>
                    </div>
                    <div className="flex items-center gap-0.5">
                      <Minus className="h-3 w-3 text-gray-400" />
                      <span>Not Marked</span>
                    </div>
                  </div>
                </div>

                {/* Week columns with attendance status icons */}
                <div className="flex gap-1 flex-wrap">
                  {courseData.meetings.map((meeting: CourseAttendanceData['meetings'][0]) => {
                    const attendance = meeting.attendance;
                    const status = attendance ? extractString(attendance.status_kehadiran as string | SqlNullString) : undefined;
                    const meetingDate = extractDate(meeting.tgl_pertemuan);
                    const dateStr = meetingDate ? meetingDate.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) : '';

                    return (
                      <div
                        key={meeting.id}
                        className="flex flex-col items-center gap-0.5 p-1.5 rounded border border-gray-200 hover:bg-gray-50 transition-colors cursor-help"
                        title={`Week ${meeting.pertemuan_ke} - ${dateStr}${meeting.topik ? ` - ${extractString(meeting.topik as string | SqlNullString)}` : ''}`}
                      >
                        <div className="text-xs font-semibold text-gray-600">W{meeting.pertemuan_ke}</div>
                        <div className="flex justify-center h-5">
                          {status ? (
                            getStatusIcon(status)
                          ) : (
                            <Minus className="h-4 w-4 text-gray-300" />
                          )}
                        </div>
                        <div className="text-xs text-gray-500 text-center leading-tight max-w-12 break-words">
                          {dateStr}
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            </div>
          )}
        </div>
      ))}
    </div>
  );
};
