/**
 * User Form Modal Component
 * Used for adding and editing users
 */

import React from 'react';
import { X, Loader, Trash2 } from 'lucide-react';
import type { UserFormData } from '../types';
import { getRoleLabel, availableRoles } from '../types';
import type { Mahasiswa, Dosen } from '@/types';

interface UserFormModalProps {
  isOpen: boolean;
  isEdit: boolean;
  formData: UserFormData;
  formError: string | null;
  actionLoading: boolean;
  students: Mahasiswa[];
  lecturers: Dosen[];
  onClose: () => void;
  onSubmit: (e: React.FormEvent) => void;
  onFormChange: (data: Partial<UserFormData>) => void;
  onAddRole: (role: string) => void;
  onRemoveRole: (index: number) => void;
  onUpdateRoleEntity: (index: number, entityType: string, entityId: string) => void;
}

export const UserFormModal: React.FC<UserFormModalProps> = ({
  isOpen,
  isEdit,
  formData,
  formError,
  actionLoading,
  students,
  lecturers,
  onClose,
  onSubmit,
  onFormChange,
  onAddRole,
  onRemoveRole,
  onUpdateRoleEntity,
}) => {
  if (!isOpen) return null;

  const title = isEdit ? 'Edit Pengguna' : 'Tambah Pengguna';
  const submitLabel = isEdit ? 'Simpan Perubahan' : 'Tambah Pengguna';

  return (
    <>
      {/* Backdrop */}
      <div className="fixed inset-0 bg-black/50 z-40" onClick={onClose} />
      
      {/* Modal */}
      <div className="fixed inset-0 flex items-center justify-center z-50 p-4 pointer-events-none">
        <div className="bg-white rounded-xl shadow-xl w-full max-w-lg max-h-[90vh] overflow-y-auto pointer-events-auto">
        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-gray-200">
          <h2 className="text-lg font-semibold text-gray-900">{title}</h2>
          <button
            onClick={onClose}
            className="p-2 text-gray-400 hover:text-gray-600 hover:bg-gray-100 rounded-lg transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Form */}
        <form onSubmit={onSubmit}>
          <div className="px-6 py-4 space-y-4">
            {formError && (
              <div className="p-3 bg-red-50 border border-red-200 rounded-lg text-red-600 text-sm">
                {formError}
              </div>
            )}

            {/* Email */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Email <span className="text-red-500">*</span>
              </label>
              <input
                type="email"
                value={formData.email}
                onChange={(e) => onFormChange({ email: e.target.value })}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                placeholder="email@example.com"
                required
              />
            </div>

            {/* Name */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Nama
              </label>
              <input
                type="text"
                value={formData.name}
                onChange={(e) => onFormChange({ name: e.target.value })}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                placeholder="Nama lengkap"
              />
            </div>

            {/* Password */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Password {!isEdit && <span className="text-red-500">*</span>}
              </label>
              <input
                type="password"
                value={formData.password}
                onChange={(e) => onFormChange({ password: e.target.value })}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                placeholder={isEdit ? 'Kosongkan jika tidak ingin mengubah' : 'Masukkan password'}
                required={!isEdit}
              />
            </div>

            {/* Roles */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                Role
              </label>
              
              {/* Existing roles */}
              <div className="space-y-2 mb-3">
                {formData.roles.map((roleObj, idx) => (
                  <RoleEntry
                    key={idx}
                    role={roleObj.role}
                    entityId={roleObj.entity_id}
                    students={students}
                    lecturers={lecturers}
                    onUpdateEntity={(entityType, entityId) =>
                      onUpdateRoleEntity(idx, entityType, entityId)
                    }
                    onRemove={() => onRemoveRole(idx)}
                  />
                ))}
              </div>

              {/* Add role dropdown */}
              <select
                onChange={(e) => {
                  if (e.target.value) {
                    onAddRole(e.target.value);
                    e.target.value = '';
                  }
                }}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                defaultValue=""
              >
                <option value="">+ Tambah Role</option>
                {availableRoles
                  .filter((r) => !formData.roles.some((fr) => fr.role === r.value))
                  .map((r) => (
                    <option key={r.value} value={r.value}>
                      {r.label}
                    </option>
                  ))}
              </select>
            </div>
          </div>

          {/* Footer */}
          <div className="px-6 py-4 border-t border-gray-200 flex justify-end gap-3">
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-2 text-gray-700 bg-gray-100 rounded-lg hover:bg-gray-200 transition-colors"
              disabled={actionLoading}
            >
              Batal
            </button>
            <button
              type="submit"
              className="px-4 py-2 text-white bg-blue-600 rounded-lg hover:bg-blue-700 transition-colors disabled:opacity-50 flex items-center gap-2"
              disabled={actionLoading}
            >
              {actionLoading && <Loader className="w-4 h-4 animate-spin" />}
              {submitLabel}
            </button>
          </div>
        </form>
      </div>
      </div>
    </>
  );
};

/**
 * Role entry component with entity selection
 */
interface RoleEntryProps {
  role: string;
  entityId?: string;
  students: Mahasiswa[];
  lecturers: Dosen[];
  onUpdateEntity: (entityType: string, entityId: string) => void;
  onRemove: () => void;
}

const RoleEntry: React.FC<RoleEntryProps> = ({
  role,
  entityId,
  students,
  lecturers,
  onUpdateEntity,
  onRemove,
}) => {
  const showStudentSelect = role === 'student' || role === 'alumni';
  const showLecturerSelect = role === 'lecturer';

  return (
    <div className="flex items-center gap-2 p-2 bg-gray-50 rounded-lg">
      <span className="text-sm font-medium text-gray-700 min-w-[80px]">
        {getRoleLabel(role)}
      </span>

      {showStudentSelect && (
        <select
          value={entityId || ''}
          onChange={(e) => onUpdateEntity('mahasiswa', e.target.value)}
          className="flex-1 px-2 py-1 text-sm border border-gray-300 rounded focus:ring-2 focus:ring-blue-500"
        >
          <option value="">Pilih Mahasiswa</option>
          {students.map((s) => (
            <option key={s.nim} value={s.nim}>
              {s.nim} - {s.nama || '(No Name)'}
            </option>
          ))}
        </select>
      )}

      {showLecturerSelect && (
        <select
          value={entityId || ''}
          onChange={(e) => onUpdateEntity('dosen', e.target.value)}
          className="flex-1 px-2 py-1 text-sm border border-gray-300 rounded focus:ring-2 focus:ring-blue-500"
        >
          <option value="">Pilih Dosen</option>
          {lecturers.map((l) => (
            <option key={l.id} value={l.id}>
              {l.id} - {l.nama || '(No Name)'}
            </option>
          ))}
        </select>
      )}

      {!showStudentSelect && !showLecturerSelect && (
        <span className="flex-1 text-sm text-gray-500">
          Tidak memerlukan entitas
        </span>
      )}

      <button
        type="button"
        onClick={onRemove}
        className="p-1 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded transition-colors"
      >
        <Trash2 className="w-4 h-4" />
      </button>
    </div>
  );
};

export default UserFormModal;
